(function() {
    'use strict';

    class IncubatorAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Inside the Incubator`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brazil / BRL, money in R$ millions unless noted).
            this.START_SURVIVAL = 41;        // historical 2-year survival
            this.TARGET_SURVIVAL = 60;       // mandate floor
            this.TARGET_FUNDING = 25;        // mandate floor, R$M follow-on per cohort
            this.SEATS = 10;                 // cohort seats
            this.MENTOR_HOURS = 2400;        // mentor-hours per cohort
            this.GRANT_POOL = 1.8;           // R$M micro-grant pool
            this.READINESS_COST = 0.7;       // R$M fundraising-readiness program
            this.SUPPORT_CAP = 4.2;          // R$M direct cohort support
            this.OVERHEAD = 2.2;             // R$M fixed overhead
            this.BUDGET_CAP = 6.4;           // R$M annual operating budget

            // Per-type two-year survival (%) and follow-on funding per venture (R$M).
            this.TYPE = {
                saas:        { surv: 58, fund: 1.8 },
                deeptech:    { surv: 30, fund: 5.2 },
                marketplace: { surv: 45, fund: 3.0 },
                social:      { surv: 50, fund: 1.2 }
            };

            // Concept-correct diagnoses.
            this.TRUE_DRIVER = `both`;
            this.TRUE_TENSION = `variance`;
            this.TRUE_SIGNAL = `track`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    survival: this.START_SURVIVAL,
                    funding: 0,
                    efficiency: 20,
                    budgetUsed: this.OVERHEAD,
                    supportUsed: 0,
                    survivalMissed: false,
                    fundingMissed: false,
                    zombies: false,
                    survivalHistory: [this.START_SURVIVAL],
                    fundingHistory: [0],
                    efficiencyHistory: [20],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING — never the textbook-correct play.
                state.decisions = {
                    driver: `deeptech`,
                    tension: `none`,
                    signal: `coach`,
                    rigor: 50,
                    saas: 3,
                    deeptech: 4,
                    marketplace: 2,
                    social: 1,
                    diversify: `concentrate`,
                    logic: `equal`,
                    readiness: `cut`,
                    concentration: 40,
                    mentor: 480,
                    gate: `loose`,
                    offramp: `redirect`,
                    board: `optics`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dr = document.getElementById(`driverInput`);
                const te = document.getElementById(`tensionInput`);
                const si = document.getElementById(`signalInput`);
                const ri = document.getElementById(`rigorInput`);
                if (dr) decisions.driver = dr.value;
                if (te) decisions.tension = te.value;
                if (si) decisions.signal = si.value;
                if (ri) decisions.rigor = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigor) || decisions.rigor < 0 || decisions.rigor > 100) {
                    warn(`warn_rigor_range`); return false;
                }
            } else if (round === 2) {
                const sa = document.getElementById(`saasInput`);
                const dt = document.getElementById(`deeptechInput`);
                const mk = document.getElementById(`marketplaceInput`);
                const so = document.getElementById(`socialInput`);
                const di = document.getElementById(`diversifyInput`);
                if (sa) decisions.saas = parseInt(sa.value, 10);
                if (dt) decisions.deeptech = parseInt(dt.value, 10);
                if (mk) decisions.marketplace = parseInt(mk.value, 10);
                if (so) decisions.social = parseInt(so.value, 10);
                if (di) decisions.diversify = di.value;
                const seats = [decisions.saas, decisions.deeptech, decisions.marketplace, decisions.social];
                if (seats.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_seats_negative`); return false;
                }
                const total = seats.reduce((a, b) => a + b, 0);
                if (total !== this.SEATS) {
                    warn(`warn_seats_total`); return false;
                }
            } else if (round === 3) {
                const lo = document.getElementById(`logicInput`);
                const re = document.getElementById(`readinessInput`);
                const co = document.getElementById(`concentrationInput`);
                const me = document.getElementById(`mentorInput`);
                if (lo) decisions.logic = lo.value;
                if (re) decisions.readiness = re.value;
                if (co) decisions.concentration = parseInt(co.value, 10);
                if (me) decisions.mentor = parseInt(me.value, 10);
                if (!Number.isFinite(decisions.concentration) || decisions.concentration < 0 || decisions.concentration > 100) {
                    warn(`warn_concentration_range`); return false;
                }
                if (!Number.isFinite(decisions.mentor) || decisions.mentor < 0 || decisions.mentor > this.MENTOR_HOURS) {
                    warn(`warn_mentor_range`); return false;
                }
            } else if (round === 4) {
                const ga = document.getElementById(`gateInput`);
                const of = document.getElementById(`offrampInput`);
                const bo = document.getElementById(`boardInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ga) decisions.gate = ga.value;
                if (of) decisions.offramp = of.value;
                if (bo) decisions.board = bo.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: survival = projected 2-year survival rate; funding = follow-on R$M;
            // eff = how well scarce support reaches the ventures that move the KPIs;
            // spend = direct cohort support consumed (R$M, against the 4.2M cap).
            let survivalDelta = 0, fundingDelta = 0, effDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the dual-KPI portfolio logic (Common Errors 1 & 2 set up here).
                if (d.driver === this.TRUE_DRIVER) {
                    survivalDelta += 5; fundingDelta += 2; effDelta += 7; coachKey = `coach_r1_driver_right`;
                } else if (d.driver === `deeptech`) {
                    survivalDelta -= 4; fundingDelta += 1; effDelta -= 4; coachKey = `coach_r1_deeptech`;
                } else if (d.driver === `saas`) {
                    survivalDelta += 3; fundingDelta -= 4; effDelta -= 4; coachKey = `coach_r1_saas`;
                } else {
                    survivalDelta -= 2; fundingDelta -= 3; effDelta -= 4; coachKey = `coach_r1_social`;
                }

                // Naming the variance/dual-KPI tension is the heart of the diagnosis.
                if (d.tension === this.TRUE_TENSION) {
                    survivalDelta += 4; fundingDelta += 2; effDelta += 6;
                    if (d.driver === this.TRUE_DRIVER) coachKey = `coach_r1_diag_sharp`;
                } else if (d.tension === `cost`) {
                    effDelta -= 6; coachKey = `coach_r1_cost`;
                } else {
                    effDelta -= 8; coachKey = `coach_r1_notension`;
                }

                // Predictive signal selection (screening under uncertainty).
                if (d.signal === this.TRUE_SIGNAL) {
                    survivalDelta += 3; fundingDelta += 1; effDelta += 4;
                } else if (d.signal === `coach`) {
                    effDelta -= 3;
                } else {
                    survivalDelta -= 3; effDelta -= 5;
                }

                // Rigor of operationalizing the mandate.
                if (d.rigor >= 60) { effDelta += 5; survivalDelta += 1; }
                else if (d.rigor <= 25) { effDelta -= 6; coachKey = `coach_r1_lowrigor`; }

                summaryKey = (d.driver === this.TRUE_DRIVER && d.tension === this.TRUE_TENSION) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Select the cohort — the blended outcome IS the projected KPI level (portfolio thinking).
                const seats = { saas: d.saas, deeptech: d.deeptech, marketplace: d.marketplace, social: d.social };
                const filled = seats.saas + seats.deeptech + seats.marketplace + seats.social;
                const denom = filled > 0 ? filled : 1;

                // Blended projected survival (% points) = seat-weighted average of type survival.
                let blendSurv = 0, projFund = 0;
                Object.keys(this.TYPE).forEach((k) => {
                    blendSurv += seats[k] * this.TYPE[k].surv;
                    projFund += seats[k] * this.TYPE[k].fund;
                });
                blendSurv = blendSurv / denom;

                // Move survival toward the blended projection (anchors the KPI to the real mix).
                survivalDelta += Math.round((blendSurv - ds.survival) * 0.85);
                // Funding is built up across rounds; selection lays the projected base.
                fundingDelta += projFund * 0.42;

                // Diversification: managing variance so one sector's failure does not sink the cohort.
                const maxSeat = Math.max(seats.saas, seats.deeptech, seats.marketplace, seats.social);
                const concentrated = maxSeat >= 6;
                if (d.diversify === `balanced` && !concentrated) {
                    survivalDelta += 4; fundingDelta += 1; effDelta += 7; coachKey = `coach_r2_balanced`;
                } else if (d.diversify === `balanced` && concentrated) {
                    // Claiming "balanced" while loading one type heavily earns no diversification credit
                    // and still carries the concentration survival penalty — the cohort's fate rides on one sector.
                    survivalDelta -= 2; effDelta += 1; coachKey = `coach_r2_saidbalanced`;
                } else if (d.diversify === `concentrate` || concentrated) {
                    effDelta -= 8; survivalDelta -= 2; coachKey = `coach_r2_concentrate`;
                } else {
                    effDelta -= 4; coachKey = `coach_r2_ignore`;
                }

                // Variance overload (Common Error 1): a deep-tech-heavy cohort craters the BLENDED
                // survival rate so hard that no amount of downstream support can lift it back to the
                // 60% mandate. Funding may still clear (deep-tech raises big rounds) — but the dual
                // mandate fails on survival, exactly as the facilitator decision tree predicts (~38%).
                if (seats.deeptech >= 6) { survivalDelta -= 14; coachKey = `coach_r2_variance`; }
                else if (seats.saas >= 7) coachKey = `coach_r2_safe`;

                summaryKey = (d.diversify === `balanced` && !concentrated && blendSurv >= 48) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Allocate scarce support (Common Errors 3 & 5 live here).
                // Allocation logic: milestone-gated > tiered > equal (fairness over outcomes).
                switch (d.logic) {
                    case `milestone`: survivalDelta += 6; fundingDelta += 2.5; effDelta += 11; coachKey = `coach_r3_milestone`; break;
                    case `tiered`: survivalDelta += 4; fundingDelta += 1.5; effDelta += 7; coachKey = `coach_r3_tiered`; break;
                    case `equal`: survivalDelta -= 2; fundingDelta -= 2; effDelta -= 8; coachKey = `coach_r3_equal`; break;
                }

                // The fundraising-readiness program is what the funding KPI actually needs.
                switch (d.readiness) {
                    case `sponsor`: spend += 0; fundingDelta += 5; effDelta += 3; coachKey = `coach_r3_sponsor`; break;
                    case `grants`: spend += this.READINESS_COST; fundingDelta += 4; survivalDelta -= 2; coachKey = `coach_r3_grants`; break;
                    case `cut`: fundingDelta -= 5; coachKey = `coach_r3_cut`; break;
                }

                // Grant concentration: spreading thinly yields weak signals; concentrating lifts the fundable.
                spend += this.GRANT_POOL;
                if (d.concentration >= 60) { fundingDelta += 2; survivalDelta += 2; effDelta += 5; }
                else if (d.concentration <= 25) { effDelta -= 6; fundingDelta -= 1; coachKey = (coachKey === `coach_r3_milestone` || coachKey === `coach_r3_tiered`) ? coachKey : `coach_r3_thin`; }

                // Mentor-hours: a concentrated push (~600–900h) closes the two most fundable rounds.
                spend += 1.5; // mentor stipends + space + programming, R$M
                if (d.mentor >= 600 && d.mentor <= 960) { fundingDelta += 3; survivalDelta += 3; effDelta += 5; }
                else if (d.mentor < 300) { fundingDelta -= 3; effDelta -= 5; coachKey = `coach_r3_starve`; }
                else if (d.mentor > 1400) { effDelta -= 6; survivalDelta -= 1; coachKey = `coach_r3_overconcentrate`; }

                summaryKey = (d.logic !== `equal` && d.readiness !== `cut`) ? `sum_r3_good` : (d.logic === `equal` ? `sum_r3_equal` : `sum_r3_weak`);
            } else if (round === 4) {
                // Graduation criteria, off-ramp discipline, board defense (Common Errors 4 & 5).
                switch (d.gate) {
                    case `calibrated`: survivalDelta += 8; fundingDelta += 2; effDelta += 8; coachKey = `coach_r4_calibrated`; break;
                    case `loose`: survivalDelta += 4; effDelta -= 10; ds.zombies = true; coachKey = `coach_r4_loose`; break;
                    case `brutal`: survivalDelta += 2; fundingDelta -= 4; effDelta -= 4; coachKey = `coach_r4_brutal`; break;
                }

                // Mid-cohort off-ramp: reallocating from failing bets closes a stronger venture's round.
                switch (d.offramp) {
                    case `offramp`: fundingDelta += 4; survivalDelta += 3; effDelta += 8; break;
                    case `redirect`: fundingDelta += 1; effDelta += 3; break;
                    case `loyalty`: fundingDelta -= 5; survivalDelta -= 2; effDelta -= 8; coachKey = `coach_r4_loyalty`; break;
                }

                // Board defense: gated evidence beats optics; loose gates corrupt the metric.
                switch (d.board) {
                    case `evidence`: survivalDelta += 4; effDelta += 5; coachKey = (d.gate === `calibrated` && d.offramp === `offramp`) ? `coach_r4_evidence` : coachKey; break;
                    case `optics`: survivalDelta -= 6; effDelta -= 8; ds.zombies = true; coachKey = `coach_r4_optics`; break;
                    case `defer`: effDelta -= 4; coachKey = `coach_r4_defer`; break;
                }

                // Conviction nudges resource efficiency.
                effDelta += Math.round((d.conviction - 55) / 9);

                summaryKey = (d.gate === `calibrated` && d.offramp === `offramp` && d.board === `evidence`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting (direct support against the R$4,2M cap; total against R$6,4M).
            ds.supportUsed = Math.round((ds.supportUsed + spend) * 100) / 100;
            ds.budgetUsed = Math.round((this.OVERHEAD + ds.supportUsed) * 100) / 100;

            // KPI movement with floors/ceilings; meters start low and keep headroom.
            ds.survival = Math.max(0, Math.min(100, ds.survival + survivalDelta));
            ds.funding = Math.max(0, ds.funding + fundingDelta);
            ds.efficiency = Math.max(0, Math.min(100, ds.efficiency + effDelta));

            // Loose graduation gates inflate the survival headline with zombies — flag and discount.
            if (ds.zombies && round >= 3) {
                ds.survival = Math.max(0, ds.survival - 6);
            }

            ds.survivalHistory.push(Math.round(ds.survival));
            ds.fundingHistory.push(Math.round(ds.funding * 10) / 10);
            ds.efficiencyHistory.push(Math.round(ds.efficiency));

            // v1.1.0: persist composite to domainState so the instructor gradebook
            // (express/results_utils.php::express_resolveDomainScore, Ruta 1) resolves a score.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            if (round === this.ROUNDS.length) {
                if (ds.survival < this.TARGET_SURVIVAL) ds.survivalMissed = true;
                if (ds.funding < this.TARGET_FUNDING) ds.fundingMissed = true;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                survival: Math.round(ds.survival),
                survivalDelta: Math.round(survivalDelta),
                funding: Math.round(ds.funding * 10) / 10,
                fundingDelta: Math.round(fundingDelta * 10) / 10,
                efficiency: Math.round(ds.efficiency),
                efficiencyDelta: Math.round(effDelta),
                supportUsed: ds.supportUsed,
                budgetUsed: ds.budgetUsed,
                zombies: ds.zombies,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

