            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const bar = document.querySelector(`.incubatorsim-budget-bar`);
                if (bar) bar.classList.toggle(`incubatorsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `R$` + (Math.round(Number(v) * 10) / 10).toFixed(1).replace(`.`, `,`) + `M / 6,4M`;
            });

            const self = this;

            // Rigor slider readout.
            const ri = document.getElementById(`rigorInput`);
            const riReadout = document.getElementById(`rigorReadout`);
            if (ri && riReadout) {
                riReadout.textContent = ri.value;
                ri.addEventListener(`input`, function() { riReadout.textContent = ri.value; });
            }

            // Grant-concentration slider readout.
            const co = document.getElementById(`concentrationInput`);
            const coReadout = document.getElementById(`concentrationReadout`);
            if (co && coReadout) {
                coReadout.textContent = co.value;
                co.addEventListener(`input`, function() { coReadout.textContent = co.value; });
            }

            // Cohort-seats live total (must equal 10).
            const seatIds = [`saasInput`, `deeptechInput`, `marketplaceInput`, `socialInput`];
            const seatsReadout = document.getElementById(`seatsReadout`);
            const recompute = function() {
                let total = 0;
                seatIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (seatsReadout) seatsReadout.textContent = total;
                const bar = document.querySelector(`.incubatorsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.SEATS) ? `#c0392b` : ``;
            };
            seatIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

