        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.survivalHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            return {
                incubatorChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.survivalHistory },
                        { data: ds.fundingHistory },
                        { data: ds.efficiencyHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged):
            // survival 0-100, funding scaled to 0-100 around a R$30M ceiling, efficiency 0-100.
            const survival = Math.round(ds.survival);
            const funding = Math.round(ds.funding * 10) / 10;
            const efficiency = Math.round(ds.efficiency);
            const fundingScore = Math.min(100, (funding / 30) * 100);
            return Math.round(survival * 0.35 + fundingScore * 0.35 + efficiency * 0.30);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const survival = Math.round(ds.survival);
            const funding = Math.round(ds.funding * 10) / 10;
            const efficiency = Math.round(ds.efficiency);

            const hitSurvival = survival >= this.TARGET_SURVIVAL;
            const hitFunding = funding >= this.TARGET_FUNDING;
            const bothHit = hitSurvival && hitFunding;
            const zombies = ds.zombies;
            // Composite: survival 0-100, funding scaled to 0-100 around a 30 R$M ceiling, efficiency 0-100.
            const composite = this._composite(ds);

            let performanceKey = `grade_lost`;
            if (bothHit && !zombies && composite >= 70) performanceKey = `grade_refunded`;
            else if (bothHit && !zombies) performanceKey = `grade_dualmet`;
            else if (bothHit && zombies) performanceKey = `grade_zombie`;
            else if (hitSurvival && !hitFunding) performanceKey = `grade_survonly`;
            else if (hitFunding && !hitSurvival) performanceKey = `grade_fundonly`;
            else if (survival > this.START_SURVIVAL + 8 || funding > 12) performanceKey = `grade_improving`;
            const performance = window.mySimulation.t(performanceKey);
            const met = bothHit && !zombies && composite >= 70;

            const insights = [];
            if (bothHit && !zombies) insights.push(window.mySimulation.t(`insight_refunded`));
            else if (bothHit && zombies) insights.push(window.mySimulation.t(`insight_zombie`));
            else if (hitSurvival && !hitFunding) insights.push(window.mySimulation.t(`insight_survonly`));
            else if (hitFunding && !hitSurvival) insights.push(window.mySimulation.t(`insight_fundonly`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (efficiency < 45) insights.push(window.mySimulation.t(`insight_loweff`));
            if (zombies) insights.push(window.mySimulation.t(`insight_zombies_flag`));
            if (bothHit && !zombies && efficiency >= 65) insights.push(window.mySimulation.t(`insight_disciplined`));

            return {
                survival: survival,
                funding: funding,
                efficiency: efficiency,
                hitSurvival: hitSurvival,
                hitFunding: hitFunding,
                bothHit: bothHit,
                zombies: zombies,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="incubatorsim-cm-badge ` + (s.met ? `incubatorsim-cm-met` : `incubatorsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.hitSurvival === false) badges.push(`<span class="incubatorsim-cm-badge incubatorsim-cm-fail">` + t(`cm_fail_surv`) + `</span>`);
            if (s.hitFunding === false) badges.push(`<span class="incubatorsim-cm-badge incubatorsim-cm-fail">` + t(`cm_fail_fund`) + `</span>`);
            if (s.zombies) badges.push(`<span class="incubatorsim-cm-badge incubatorsim-cm-fail">` + t(`cm_fail_zombie`) + `</span>`);
            const kpi = (label, val) => `<div class="incubatorsim-cm-metric"><div class="incubatorsim-cm-metric-val">` + val + `</div><div class="incubatorsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_survival`), (s.survival != null ? Math.round(s.survival) : 0) + `%`)
                + kpi(t(`cm_funding`), `R$` + (s.funding != null ? s.funding : 0) + `M`)
                + kpi(t(`cm_efficiency`), (s.efficiency != null ? Math.round(s.efficiency) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="incubatorsim-cm">`
                + `<div class="incubatorsim-cm-head"><div class="incubatorsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="incubatorsim-cm-scorewrap"><span class="incubatorsim-cm-score">` + score + `</span><span class="incubatorsim-cm-score-max">/100</span></div>`
                + `<div class="incubatorsim-cm-grade">` + grade + `</div>`
                + `<div class="incubatorsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="incubatorsim-cm-metrics">` + kpis + `</div>`
                + `<div class="incubatorsim-cm-insights"><div class="incubatorsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.zombies && state.currentPeriod >= 3) return window.mySimulation.t(`hint_zombie`);
            if (ds.efficiency < 35) return window.mySimulation.t(`hint_eff`);
            if (state.currentPeriod >= 2 && ds.survival < 50 && ds.funding < 12) return window.mySimulation.t(`hint_behind`);
            if (state.currentPeriod >= 3 && ds.survival >= this.TARGET_SURVIVAL && ds.funding < this.TARGET_FUNDING) return window.mySimulation.t(`hint_funding`);
            if (state.currentPeriod >= 3 && ds.funding >= this.TARGET_FUNDING && ds.survival < this.TARGET_SURVIVAL) return window.mySimulation.t(`hint_survival`);
            if (ds.survival >= this.TARGET_SURVIVAL && ds.funding >= this.TARGET_FUNDING && ds.efficiency >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

